/**
 * @fileoverview Default drum/beat sample data for the Harmonicarium synthesizer.
 * This file contains Base64-encoded WAV samples used as the built-in
 * beat/drum presets for the polyrhythm mode.
 *
 * @module synth-beats-default
 * @memberof HUM.Synth
 * @version 0.8.2
 * @author Walter G. Mantovani <armonici.it@gmail.com>
 * @copyright (C) 2017-2026 Walter G. Mantovani
 * @license AGPL-3.0-or-later
 *
 * @description
 * This file is part of HARMONICARIUM, a web app which allows users to play
 * the Harmonic Series dynamically by changing its fundamental tone in real-time.
 * It is available in its latest version from:
 * https://github.com/IndustrieCreative/Harmonicarium
 *
 * This program is free software: you can redistribute it and/or modify
 * it under the terms of the GNU Affero General Public License as
 * published by the Free Software Foundation, either version 3 of the
 * License, or (at your option) any later version.
 *
 * This program is distributed in the hope that it will be useful,
 * but WITHOUT ANY WARRANTY; without even the implied warranty of
 * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the
 * GNU Affero General Public License for more details.
 *
 * You should have received a copy of the GNU Affero General Public License
 * along with this program.  If not, see <http://www.gnu.org/licenses/>.
 *
 * @note The WAV sample files are embedded as Base64 data URIs so that they
 * can be loaded automatically under the `file://` protocol without triggering
 * CORS errors that would block a `fetch()` of an external resource.
 */

"use strict";

/**
 * Default drum/beat samples bundled with the synthesizer for polyrhythm mode.
 *
 * @memberof HUM.Synth
 *
 * @type {Object}
 *
 * @property {Object} kick   - Kick drum sample.
 * @property {Object} snare  - Snare drum sample.
 * @property {Object} hat    - Hi-hat sample.
 * @property {Object} tom    - Tom drum sample.
 *
 * @description
 * Each entry has:
 *   - `name` {string}  Human-readable label shown in the UI.
 *   - `data` {string}  WAV audio file encoded as a Base64 data URI
 *     (`data:audio/wav;base64,…`), ready to be decoded by the Web Audio API
 *     `AudioContext.decodeAudioData()`.
 *
 * The audio data is stored inline as Base64 data URIs so that the samples
 * load correctly under the `file://` protocol without requiring a web server.
 *
 * @example <caption>Re-encode a WAV file to Base64 with OpenSSL:</caption>
 * #openssl base64 -in /path/to/audio.wav -out /path/to/audio.base64
 */
HUM.Synth.defaultBeats = {
    // The kick drum sample in .wav format
    kick: {
        name: "kick",
        data: `data:audio/wav;base64,`
    },
    // The snare drum sample in .wav format
    snare: {
        name: "snare",
        data: `data:audio/wav;base64,`
    },
    // The hi-hat sample in .wav format
    hat: {
        name: "hat",
        data: `data:audio/wav;base64,`
    },
    // The tom drum sample in .wav format
    tom: {
        name: "tom",
        data: `data:audio/wav;base64,`
    }
};
